/* DAWAH X — ahmad, অধ্যায় 48 · খণ্ড 48 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][48]=[[9401,9401,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏مَوْلَى ‏ ‏أَبِي أَحْمَدَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى بِهِمْ فَسَهَا فَلَمَّا سَلَّمَ سَجَدَ سَجْدَتَيْنِ ثُمَّ سَلَّمَ ‏","","",""],[9402,9402,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ فُلَانًا ‏ ‏يُصَلِّي بِاللَّيْلِ فَإِذَا أَصْبَحَ سَرَقَ قَالَ إِنَّهُ ‏ ‏سَيَنْهَاهُ مَا يَقُولُ ‏","","",""],[9403,9403,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَامِلًا ‏ ‏الْحَسَنَ بْنَ عَلِيٍّ ‏ ‏عَلَى ‏ ‏عَاتِقِهِ ‏ ‏وَلُعَابُهُ يَسِيلُ عَلَيْهِ ‏","","",""],[9404,9404,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَرُونِي ‏ ‏مَا تَرَكْتُكُمْ فَإِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ ‏ ‏بِسُؤَالِهِمْ وَاخْتِلَافِهِمْ عَلَى أَنْبِيَائِهِمْ فَإِذَا أَمَرْتُكُمْ بِأَمْرٍ فَاتَّبِعُوهُ مَا اسْتَطَعْتُمْ وَإِذَا نَهَيْتُكُمْ عَنْ أَمْرٍ فَاجْتَنِبُوهُ ‏","","",""],[9405,9405,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏لَهُ سَكْتَةٌ فِي الصَّلَاةِ ‏","","",""],[9406,9406,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏كَامِلٌ أَبُو الْعَلَاءِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَجِبَ رَبُّنَا عَزَّ وَجَلَّ مِنْ قَوْمٍ يُقَادُونَ إِلَى الْجَنَّةِ فِي السَّلَاسِلِ ‏","","",""],[9407,9407,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏كَامِلٌ أَبُو الْعَلَاءِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَعَوَّذُوا بِاللَّهِ مِنْ رَأْسِ السَّبْعِينَ وَإِمَارَةِ الصِّبْيَانِ ‏","","",""],[9408,9408,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ ‏ ‏الطُّفَيْلُ ‏ ‏وَأَصْحَابُهُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ ‏ ‏دَوْسًا ‏ ‏قَدْ اسْتَعْصَتْ قَالَ ‏ ‏اللَّهُمَّ اهْدِ ‏ ‏دَوْسًا ‏ ‏وَأْتِ بِهِمْ ‏","","",""],[9409,9409,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ مَوْهَبٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مُسْلِمٍ ‏ ‏يَنْصِبُ ‏ ‏وَجْهَهُ لِلَّهِ عَزَّ وَجَلَّ فِي مَسْأَلَةٍ إِلَّا أَعْطَاهَا إِيَّاهُ إِمَّا أَنْ يُعَجِّلَهَا لَهُ وَإِمَّا أَنْ يَدَّخِرَهَا لَهُ ‏","","",""],[9410,9410,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏مَوْلَى ‏ ‏الْأَسْوَدِ بْنِ سُفْيَانَ ‏ ‏عَنِ ‏ ‏ابْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ إِلَى الصَّلَاةِ فَلَمَّا كَبَّرَ انْصَرَفَ ‏ ‏وَأَوْمَأَ ‏ ‏إِلَيْهِمْ أَيْ كَمَا أَنْتُمْ ثُمَّ خَرَجَ فَاغْتَسَلَ ثُمَّ جَاءَ وَرَأْسُهُ يَقْطُرُ فَصَلَّى بِهِمْ فَلَمَّا صَلَّى قَالَ ‏ ‏إِنِّي كُنْتُ ‏ ‏جُنُبًا ‏ ‏فَنَسِيتُ أَنْ أَغْتَسِلَ ‏","","",""],[9411,9411,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَنْعَتُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ كَانَ ‏ ‏شَبْحَ الذِّرَاعَيْنِ أَهْدَبَ ‏ ‏أَشْفَارِ ‏ ‏الْعَيْنَيْنِ بَعِيدَ مَا بَيْنَ ‏ ‏الْمَنْكِبَيْنِ ‏ ‏يُقْبِلُ إِذَا أَقْبَلَ جَمِيعًا ‏ ‏وَيُدْبِرُ ‏ ‏إِذَا ‏ ‏أَدْبَرَ ‏ ‏جَمِيعًا ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏فِي حَدِيثِهِ بِأَبِي وَأُمِّي لَمْ يَكُنْ ‏ ‏فَاحِشًا ‏ ‏وَلَا ‏ ‏مُتَفَحِّشًا ‏ ‏وَلَا ‏ ‏سَخَّابًا ‏ ‏بِالْأَسْوَاقِ ‏","","",""],[9412,9412,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏وَهَاشِمُ بْنُ الْقَاسِمِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي ‏ ‏أُمِّ الْقُرْآنِ ‏ ‏هِيَ ‏ ‏أُمُّ الْقُرْآنِ ‏ ‏وَهِيَ ‏ ‏السَّبْعُ الْمَثَانِي ‏ ‏وَهِيَ ‏ ‏الْقُرْآنُ الْعَظِيمُ ‏","","",""],[9413,9413,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏وَهَاشِمٌ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَوْلَا أَمْرَانِ لَأَحْبَبْتُ أَنْ أَكُونَ مَمْلُوكًا وَذَلِكَ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا خَلَقَ اللَّهُ عَبْدًا يُؤَدِّي حَقَّ اللَّهِ وَحَقَّ سَيِّدِهِ إِلَّا وَفَّاهُ اللَّهُ أَجْرَهُ مَرَّتَيْنِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏إِنَّ الْمَمْلُوكَ لَا يَسْتَطِيعُ أَنْ يَصْنَعَ فِي مَالِهِ شَيْئًا ‏","","",""],[9414,9414,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْحَمْدُ لِلَّهِ ‏ ‏أُمُّ الْقُرْآنِ ‏ ‏وَأُمُّ الْكِتَابِ ‏ ‏وَالسَّبْعُ الْمَثَانِي ‏","","",""],[9415,9415,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّكُمْ سَتَحْرِصُونَ عَلَى الْإِمَارَةِ وَسَتَصِيرُ نَدَامَةً وَحَسْرَةً يَوْمَ الْقِيَامَةِ فَبِئْسَتْ الْمُرْضِعَةُ ‏ ‏وَنِعْمَتْ الْفَاطِمَةُ ‏","","",""],[9416,9416,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏اخْتَصَمَ ‏ ‏آدَمُ ‏ ‏وَمُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِمَا وَسَلَّمَ فَخَصَمَ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏ ‏فَقَالَ ‏ ‏مُوسَى ‏ ‏أَنْتَ ‏ ‏آدَمُ ‏ ‏الَّذِي أَشْقَيْتَ النَّاسَ وَأَخْرَجْتَهُمْ مِنْ الْجَنَّةِ فَقَالَ ‏ ‏آدَمُ ‏ ‏أَنْتَ ‏ ‏مُوسَى ‏ ‏الَّذِي ‏ ‏اصْطَفَاكَ ‏ ‏اللَّهُ بِرِسَالَاتِهِ وَبِكَلَامِهِ وَأَنْزَلَ عَلَيْكَ التَّوْرَاةَ أَلَيْسَ تَجِدُ فِيهَا أَنْ قَدْ قَدَّرَهُ اللَّهُ عَلَيَّ قَبْلَ أَنْ يَخْلُقَنِي قَالَ بَلَى قَالَ ‏ ‏عَمْرُو بْنُ سَعِيدٍ ‏ ‏وَابْنُ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيُّ ‏ ‏فَحَجَّ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏يَكْفِينِي أَوَّلُ الْحَدِيثِ فَخَصَمَ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏ ‏عَلَيْهِمَا السَّلَام ‏","","",""],[9417,9417,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏اشْتَرُوا أَنْفُسَكُمْ مِنْ اللَّهِ يَا ‏ ‏صَفِيَّةُ عَمَّةَ رَسُولِ اللَّهِ ‏ ‏وَيَا ‏ ‏فَاطِمَةُ بِنْتَ رَسُولِ اللَّهِ ‏ ‏اشْتَرِيَا أَنْفُسَكُمَا مِنْ اللَّهِ لَا ‏ ‏أُغْنِي عَنْكُمَا مِنْ اللَّهِ شَيْئًا سَلَانِي مِنْ مَالِي مَا شِئْتُمَا ‏","","",""],[9418,9418,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَيَأْتِيَنَّ عَلَى أَحَدِكُمْ يَوْمٌ لَأَنْ يَرَانِي ثُمَّ لَأَنْ يَرَانِي أَحَبُّ إِلَيْهِ مِنْ أَنْ يَكُونَ لَهُ مِثْلُ أَهْلِهِ وَمَالِهِ ‏","","",""],[9419,9419,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسْتَقِيمُ لَكَ الْمَرْأَةُ عَلَى خَلِيقَةٍ وَاحِدَةٍ إِنَّمَا هِيَ كَالضِّلَعِ إِنْ تُقِمْهَا تَكْسِرْهَا وَإِنْ تَتْرُكْهَا تَسْتَمْتِعْ بِهَا وَفِيهَا عِوَجٌ ‏","","",""],[9420,9420,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ وَفِي مُؤَخَّرِ الصُّفُوفِ رَجُلٌ فَأَسَاءَ الصَّلَاةَ فَلَمَّا سَلَّمَ نَادَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا فُلَانُ أَلَا تَتَّقِي اللَّهَ أَلَا ‏ ‏تَرَى كَيْفَ تُصَلِّي إِنَّكُمْ تَرَوْنَ أَنَّهُ ‏ ‏يَخْفَى عَلَيَّ شَيْءٌ مِمَّا تَصْنَعُونَ وَاللَّهِ ‏ ‏إِنِّي لَأَرَى مِنْ خَلْفِي كَمَا أَرَى مِنْ بَيْنِ يَدَيَّ ‏","","",""],[9421,9421,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ نِسَاءٍ رَكِبْنَ الْإِبِلَ صَالِحُ نِسَاءِ ‏ ‏قُرَيْشٍ ‏ ‏أَحْنَاهُ عَلَى وَلَدٍ فِي صِغَرِهِ وَأَرْعَاهُ عَلَى زَوْجٍ فِي ذَاتِ يَدِهِ ‏","","",""],[9422,9422,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمِسْكِينَ لَيْسَ بِالَّذِي تَرُدُّهُ التَّمْرَةُ وَلَكِنَّ الْمِسْكِينَ الَّذِي لَا يَسْأَلُ النَّاسَ وَلَا يُفْطَنُ لَهُ فَيُعْطَى ‏","","",""],[9423,9423,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَمُحَمَّدٌ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏أَبَا صَالِحٍ السَّمَّانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَاتَلَ أَحَدُكُمْ فَلْيَجْتَنِبْ الْوَجْهَ ‏","","",""],[9424,9424,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ أَهْلِ عَمَلٍ بَابٌ مِنْ أَبْوَابِ الْجَنَّةِ يُدْعَوْنَ بِذَلِكَ الْعَمَلِ وَلِأَهْلِ الصِّيَامِ بَابٌ يُدْعَوْنَ مِنْهُ يُقَالُ لَهُ ‏ ‏الرَّيَّانُ ‏ ‏فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَا رَسُولَ اللَّهِ هَلْ أَحَدٌ يُدْعَى مِنْ تِلْكَ الْأَبْوَابِ كُلِّهَا قَالَ نَعَمْ وَأَنَا أَرْجُو أَنْ تَكُونَ مِنْهُمْ يَا ‏ ‏أَبَا بَكْرٍ ‏","","",""],[9425,9425,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَزَلَ نَبِيٌّ مِنْ الْأَنْبِيَاءِ تَحْتَ شَجَرَةٍ ‏ ‏فَلَدَغَتْهُ نَمْلَةٌ فَأَمَرَ ‏ ‏بِجَهَازِهِ ‏ ‏فَأُخْرِجَ مِنْ تَحْتِهَا ثُمَّ أَمَرَ بِهَا فَأُحْرِقَتْ بِالنَّارِ فَأَوْحَى اللَّهُ عَزَّ وَجَلَّ إِلَيْهِ فَهَلَّا نَمْلَةً وَاحِدَةً ‏","","",""],[9426,9426,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ الْمُغِيرَةِ بْنِ مُعَيْقِيبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمَانَ بْنِ عَبْدٍ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏لَمْ يُضْبَطْ إِسْنَادُهُ إِنَّمَا هُوَ ‏ ‏سُلَيْمَانُ بْنُ عَمْرِو بْنِ عَبْدٍ الْعُتْوَارِيُّ ‏ ‏وَهُوَ صَاحِبُ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَبُو الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏وَعَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ إِنِّي أَتَّخِذُ عِنْدَكَ ‏ ‏عَهْدًا ‏ ‏لَنْ تُخْلِفَنِيهِ فَإِنَّمَا أَنَا بَشَرٌ فَأَيُّ الْمُؤْمِنِينَ آذَيْتُهُ أَوْ شَتَمْتُهُ أَوْ لَعَنْتُهُ أَوْ جَلَدْتُهُ فَاجْعَلْهَا لَهُ زَكَاةً وَصَلَاةً وَقُرْبَةً تُقَرِّبُهُ بِهَا إِلَيْكَ يَوْمَ الْقِيَامَةِ ‏","","",""],[9427,9427,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏سَجَدَ فِي ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏فَقُلْتُ سَجَدْتَ فِي سُورَةٍ مَا يُسْجَدُ فِيهَا قَالَ إِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْجُدُ فِيهَا ‏","","",""],[9428,9428,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَالَ الْقَارِئُ ‏ { ‏غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ‏} ‏فَقَالَ مَنْ خَلْفَهُ آمِينَ فَوَافَقَ ذَلِكَ قَوْلَ أَهْلِ السَّمَاءِ آمِينَ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[9429,9429,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَذِنَ اللَّهُ عَزَّ وَجَلَّ لِشَيْءٍ كَإِذْنِهِ لِنَبِيٍّ ‏ ‏يَتَغَنَّى ‏ ‏بِالْقُرْآنِ يَجْهَرُ بِهِ ‏","","",""],[9430,9430,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَسْجِدَ فَسَمِعَ قِرَاءَةَ رَجُلٍ فَقَالَ مَنْ هَذَا قِيلَ ‏ ‏عَبْدُ اللَّهِ بْنُ قَيْسٍ ‏ ‏فَقَالَ ‏ ‏لَقَدْ أُوتِيَ هَذَا مِنْ مَزَامِيرِ آلِ ‏ ‏دَاوُدَ ‏","","",""],[9431,9431,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأَسْتَغْفِرُ اللَّهَ عَزَّ وَجَلَّ وَأَتُوبُ إِلَيْهِ كُلَّ يَوْمٍ مِائَةَ مَرَّةٍ ‏","","",""],[9432,9432,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةُ ‏ ‏مَنْ ‏ ‏أَحْدَثَ ‏ ‏فِيهَا ‏ ‏حَدَثًا ‏ ‏أَوْ ‏ ‏آوَى ‏ ‏مُحْدِثًا ‏ ‏أَوْ ‏ ‏تَوَلَّى ‏ ‏غَيْرَ ‏ ‏مَوْلَاهُ ‏ ‏فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يَقْبَلُ اللَّهُ مِنْهُ ‏ ‏صَرْفًا ‏ ‏وَلَا ‏ ‏عَدْلًا ‏","","",""],[9433,9433,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ جَاءَ ‏ ‏مَاعِزُ بْنُ مَالِكٍ الْأَسْلَمِيُّ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي قَدْ زَنَيْتُ فَأَعْرَضَ عَنْهُ ثُمَّ جَاءَ مِنْ ‏ ‏شِقِّهِ ‏ ‏الْأَيْمَنِ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي قَدْ زَنَيْتُ فَأَعْرَضَ عَنْهُ ثُمَّ جَاءَهُ مِنْ ‏ ‏شِقِّهِ ‏ ‏الْأَيْسَرِ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنِّي قَدْ زَنَيْتُ فَقَالَ لَهُ ذَلِكَ أَرْبَعَ مَرَّاتٍ فَقَالَ انْطَلِقُوا بِهِ فَارْجُمُوهُ وَقَالَ فَانْطَلَقُوا بِهِ فَلَمَّا مَسَّتْهُ الْحِجَارَةُ ‏ ‏أَدْبَرَ ‏ ‏وَاشْتَدَّ فَاسْتَقْبَلَهُ ‏ ‏رَجُلٌ ‏ ‏فِي يَدِهِ لَحْيُ جَمَلٍ فَضَرَبَهُ بِهِ فَذُكِرَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِرَارُهُ حِينَ مَسَّتْهُ الْحِجَارَةُ قَالَ فَهَلَّا تَرَكْتُمُوهُ ‏","","",""],[9434,9434,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُ الدِّينُ ظَاهِرًا مَا ‏ ‏عَجَّلَ ‏ ‏النَّاسُ الْفِطْرَ إِنَّ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏يُؤَخِّرُونَ ‏","","",""],[9435,9435,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُ الْبَلَاءُ بِالْمُؤْمِنِ أَوْ الْمُؤْمِنَةِ فِي جَسَدِهِ وَمَالِهِ وَوَلَدِهِ حَتَّى يَلْقَى اللَّهَ عَزَّ وَجَلَّ وَمَا عَلَيْهِ مِنْ خَطِيئَةٍ ‏","","",""],[9436,9436,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْبَرِي هَذَا عَلَى ‏ ‏تُرْعَةٍ ‏ ‏مِنْ ‏ ‏تُرَعِ ‏ ‏الْجَنَّةِ ‏","","",""],[9437,9437,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غِفَارُ ‏ ‏وَأَسْلَمُ ‏ ‏وَمُزَيْنَةُ ‏ ‏وَمَنْ كَانَ مِنْ ‏ ‏جُهَيْنَةَ ‏ ‏خَيْرٌ مِنْ الْحَيَّيْنِ الْحَلِيفَيْنِ ‏ ‏أَسَدٍ ‏ ‏وَغَطَفَانَ ‏ ‏وَهَوَازِنَ ‏ ‏وَتَمِيمٍ ‏ ‏فَإِنَّهُمْ أَهْلُ الْخَيْلِ ‏ ‏وَالْوَبَرِ ‏","","",""],[9438,9438,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَرَكَ مَالًا فَلِأَهْلِهِ وَمَنْ تَرَكَ ‏ ‏ضِيَاعًا ‏ ‏فَإِلَيَّ ‏","","",""],[9439,9439,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَدْنَى أَهْلِ الْجَنَّةِ مَنْزِلَةً مَنْ يَتَمَنَّى عَلَى اللَّهِ عَزَّ وَجَلَّ فَيُقَالُ لَكَ ذَلِكَ وَمِثْلُهُ مَعَهُ إِلَّا أَنَّهُ يُلَقَّنُ فَيُقَالُ لَهُ كَذَا وَكَذَا فَيُقَالُ لَكَ ذَلِكَ وَمِثْلُهُ مَعَهُ فَقَالَ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيُقَالُ لَكَ ذَلِكَ وَعَشَرَةُ أَمْثَالِهِ ‏","","",""],[9440,9440,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَّتْ ‏ ‏النَّارُ وَالْجَنَّةُ فَقَالَتْ النَّارُ يَدْخُلُنِي الْجَبَّارُونَ وَالْمُتَكَبِّرُونَ وَقَالَتْ الْجَنَّةُ يَدْخُلُنِي الضُّعَفَاءُ وَالْمَسَاكِينُ فَقَالَ اللَّهُ عَزَّ وَجَلَّ لِلنَّارِ ‏ ‏أَنْتِ عَذَابِي أَنْتَقِمُ بِكِ مِمَّنْ شِئْتُ وَقَالَ لِلْجَنَّةِ أَنْتِ رَحْمَتِي أَرْحَمُ بِكِ مَنْ شِئْتُ ‏","","",""],[9441,9441,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أُحِبُّ أَنَّ لِي ‏ ‏أُحُدًا ‏ ‏ذَهَبًا يَمُرُّ عَلَيَّ ثَالِثَةٌ وَعِنْدِي مِنْهُ فَأَجِدُ مَنْ يَقْبَلُهُ مِنِّي إِلَّا أَنْ ‏ ‏أَرْصُدَهُ ‏ ‏فِي دَيْنٍ يَكُونُ عَلَيَّ ‏","","",""],[9442,9442,"","","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَخْرُجَ ثَلَاثُونَ كَذَّابًا رِجَالًا كُلُّهُمْ يَكْذِبُ عَلَى اللَّهِ عَزَّ وَجَلَّ وَرَسُولِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[9443,9443,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَتَتَّبِعُنَّ سُنَنَ مَنْ كَانَ قَبْلَكُمْ ‏ ‏بَاعًا ‏ ‏بِبَاعٍ ‏ ‏وَذِرَاعًا بِذِرَاعٍ وَشِبْرًا بِشِبْرٍ حَتَّى لَوْ دَخَلُوا فِي جُحْرِ ضَبٍّ لَدَخَلْتُمْ مَعَهُمْ قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏الْيَهُودُ ‏ ‏وَالنَّصَارَى ‏ ‏قَالَ فَمَنْ إِذًا ‏","","",""],[9444,9444,"","","‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَمَا أَنَا عَلَى بِئْرٍ أَسْقِي فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَنَزَعَ ‏ ‏ذَنُوبًا ‏ ‏أَوْ ‏ ‏ذَنُوبَيْنِ ‏ ‏وَفِيهِمَا ضَعْفٌ وَاللَّهُ يَغْفِرُ لَهُ ثُمَّ جَاءَ ‏ ‏عُمَرُ ‏ ‏رَحِمَهُ اللَّهُ ‏ ‏فَنَزَعَ ‏ ‏حَتَّى اسْتَحَالَتْ فِي يَدِهِ ‏ ‏غَرْبًا ‏ ‏وَضَرَبَ النَّاسُ ‏ ‏بِعَطَنٍ ‏ ‏فَلَمْ أَرَ ‏ ‏عَبْقَرِيًّا ‏ ‏يَفْرِي ‏ ‏فَرْيَهُ ‏","","",""],[9445,9445,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ قَالَ ‏ ‏يَهُودِيٌّ ‏ ‏بِسُوقِ ‏ ‏الْمَدِينَةِ ‏ ‏وَالَّذِي ‏ ‏اصْطَفَى ‏ ‏مُوسَى ‏ ‏عَلَى الْبَشَرِ قَالَ ‏ ‏فَلَطَمَهُ ‏ ‏رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ تَقُولُ هَذَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِينَا قَالَ فَأَتَى الْيَهُودِيُّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏وَنُفِخَ فِي الصُّورِ فَصَعِقَ مَنْ فِي السَّمَوَاتِ وَمَنْ فِي الْأَرْضِ إِلَّا مَنْ شَاءَ اللَّهُ ثُمَّ نُفِخَ فِيهِ أُخْرَى فَإِذَا هُمْ قِيَامٌ يَنْظُرُونَ ‏} ‏قَالَ فَأَكُونُ أَوَّلَ مَنْ يَرْفَعُ رَأْسَهُ فَإِذَا ‏ ‏مُوسَى ‏ ‏آخِذٌ بِقَائِمَةٍ مِنْ قَوَائِمِ الْعَرْشِ فَلَا أَدْرِي أَرَفَعَ رَأْسَهُ قَبْلِي أَمْ كَانَ مِمَّنْ ‏ ‏اسْتَثْنَى ‏ ‏اللَّهُ وَمَنْ قَالَ أَنِّي خَيْرٌ مِنْ ‏ ‏يُونُسَ بْنِ مَتَّى ‏ ‏فَقَدْ كَذَبَ ‏","","",""],[9446,9446,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏إِذَا أَحَبَّ الْعَبْدُ لِقَائِي أَحْبَبْتُ لِقَاءَهُ وَإِذَا كَرِهَ الْعَبْدُ لِقَائِي كَرِهْتُ لِقَاءَهُ ‏ ‏قَالَ ‏ ‏فَقِيلَ ‏ ‏لِأَبِي هُرَيْرَةَ ‏ ‏مَا مِنَّا مِنْ أَحَدٍ إِلَّا وَهُوَ يَكْرَهُ الْمَوْتَ وَيَفْظَعُ بِهِ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏إِنَّهُ إِذَا كَانَ ذَلِكَ كَشَفَ بِهِ ‏","","",""],[9447,9447,"","","‏ ‏وَبِالْإِسْنَادِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ فُقَرَاءُ الْمُؤْمِنِينَ الْجَنَّةَ قَبْلَ الْأَغْنِيَاءِ بِنِصْفِ يَوْمٍ خَمْسِ مِائَةِ سَنَةٍ ‏","","",""],[9448,9448,"","","‏ ‏وَبِالْإِسْنَادِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏وَمَنْ أَظْلَمُ مِمَّنْ خَلَقَ كَخَلْقِي فَلْيَخْلُقُوا بَعُوضَةً أَوْ لِيَخْلُقُوا ذَرَّةً ‏","","",""],[9449,9449,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا لَمْ تَجِدُوا إِلَّا ‏ ‏مَرَابِضَ ‏ ‏الْغَنَمِ ‏ ‏وَمَعَاطِنَ ‏ ‏الْإِبِلِ فَصَلُّوا فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ وَلَا تُصَلُّوا فِي ‏ ‏مَعَاطِنِ ‏ ‏الْإِبِلِ ‏","","",""],[9450,9450,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ فِي الْمَسْجِدِ خَرَجَ إِلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ انْطَلِقُوا إِلَى ‏ ‏يَهُودَ ‏ ‏فَخَرَجْنَا مَعَهُ حَتَّى جِئْنَا ‏ ‏بَيْتَ الْمِدْرَاسِ ‏ ‏فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَادَاهُمْ يَا ‏ ‏مَعْشَرَ ‏ ‏الْيَهُودِ ‏ ‏أَسْلِمُوا تَسْلَمُوا فَقَالُوا قَدْ بَلَّغْتَ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏قَالَ ذَاكَ أُرِيدُ ثُمَّ قَالَهَا الثَّالِثَةَ فَقَالَ اعْلَمُوا أَنَّ الْأَرْضَ لِلَّهِ وَرَسُولِهِ وَإِنِّي أُرِيدُ أَنْ ‏ ‏أُجْلِيَكُمْ ‏ ‏مِنْ هَذِهِ الْأَرْضِ فَمَنْ وَجَدَ مِنْكُمْ بِمَالِهِ شَيْئًا فَلْيَبِعْهُ وَإِلَّا فَاعْلَمُوا أَنَّ الْأَرْضَ لِلَّهِ عَزَّ وَجَلَّ وَرَسُولِهِ ‏","","",""],[9451,9451,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ لَمَّا فُتِحَتْ ‏ ‏خَيْبَرُ ‏ ‏أُهْدِيَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَاةٌ فِيهَا سُمٌّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اجْمَعُوا لِي مَنْ كَانَ هَاهُنَا مِنْ ‏ ‏الْيَهُودِ ‏ ‏فَجَمَعُوا لَهُ فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي سَائِلُكُمْ عَنْ شَيْءٍ فَهَلْ أَنْتُمْ صَادِقِيَّ عَنْهُ قَالُوا نَعَمْ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَبُوكُمْ قَالُوا أَبُونَا فُلَانٌ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَبْتُمْ أَبُوكُمْ فُلَانٌ قَالُوا صَدَقْتَ ‏ ‏وَبَرَرْتَ ‏ ‏قَالَ لَهُمْ هَلْ أَنْتُمْ صَادِقِيَّ عَنْ شَيْءٍ سَأَلْتُكُمْ عَنْهُ قَالُوا نَعَمْ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏وَإِنْ كَذَبْنَاكَ عَرَفْتَ كَذِبَنَا كَمَا عَرَفْتَهُ فِي أَبِينَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَهْلُ النَّارِ قَالُوا نَكُونُ فِيهَا يَسِيرًا ثُمَّ تَخْلُفُونَنَا فِيهَا فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا نَخْلُفُكُمْ فِيهَا أَبَدًا ثُمَّ قَالَ لَهُمْ هَلْ أَنْتُمْ صَادِقِيَّ عَنْ شَيْءٍ سَأَلْتُكُمْ عَنْهُ فَقَالُوا نَعَمْ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَقَالَ هَلْ جَعَلْتُمْ فِي هَذِهِ الشَّاةِ سُمًّا قَالُوا نَعَمْ قَالَ فَمَا حَمَلَكُمْ عَلَى ذَلِكَ قَالُوا أَرَدْنَا إِنْ كُنْتَ كَاذِبًا نَسْتَرِيحُ مِنْكَ وَإِنْ كُنْتَ نَبِيًّا لَمْ تَضُرَّكَ ‏","","",""],[9452,9452,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ الْأَنْبِيَاءِ نَبِيٌّ إِلَّا قَدْ أُعْطِيَ مِنْ ‏ ‏الْآيَاتِ ‏ ‏مَا مِثْلَهُ آمَنَ عَلَيْهِ الْبَشَرُ وَإِنَّمَا كَانَ الَّذِي أُوتِيتُهُ وَحْيًا أَوْحَاهُ اللَّهُ إِلَيَّ فَأَرْجُو أَنْ أَكُونَ أَكْثَرَهُمْ تَابِعًا يَوْمَ الْقِيَامَةِ ‏","","",""],[9453,9453,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَبَّادِ بْنِ أَبِي سَعِيدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْأَرْبَعِ مِنْ عِلْمٍ لَا يَنْفَعُ وَمِنْ قَلْبٍ لَا يَخْشَعُ وَمِنْ نَفْسٍ لَا تَشْبَعُ وَمِنْ دُعَاءٍ لَا يُسْمَعُ ‏","","",""],[9454,9454,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بُكَيْرُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نُعَيْمٍ أَبِي عَبْدِ اللَّهِ الْمُجْمِرِ ‏ ‏أَنَّهُ قَالَ صَلَّيْتُ مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَوْقَ هَذَا الْمَسْجِدِ ‏ ‏فَقَرَأَ ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏فَسَجَدَ فِيهَا وَقَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْجُدُ فِيهَا ‏","","",""],[9455,9455,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بُكَيْرٌ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا ‏ ‏يُنَجِّي أَحَدًا مِنْكُمْ عَمَلُهُ ‏ ‏فَقَالَ رَجُلٌ وَلَا أَنْتَ يَا رَسُولَ اللَّهِ فَقَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ بِرَحْمَتِهِ وَلَكِنْ ‏ ‏سَدِّدُوا ‏","","",""],[9456,9456,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ الْمَقْبُرِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ سَنَةٍ ‏","","",""],[9457,9457,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْلًا قِبَلَ ‏ ‏نَجْدٍ ‏ ‏فَجَاءَتْ بِرَجُلٍ مِنْ ‏ ‏بَنِي حَنِيفَةَ ‏ ‏ثُمَامَةُ بْنُ أُثَالٍ ‏ ‏سَيِّدُ أَهْلِ ‏ ‏الْيَمَامَةِ ‏ ‏فَرَبَطُوهُ ‏ ‏بِسَارِيَةٍ ‏ ‏مِنْ ‏ ‏سَوَارِي ‏ ‏الْمَسْجِدِ فَخَرَجَ إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ مَاذَا عِنْدَكَ يَا ‏ ‏ثُمَامَةُ ‏ ‏قَالَ عِنْدِي يَا ‏ ‏مُحَمَّدُ ‏ ‏خَيْرٌ إِنْ تَقْتُلْ تَقْتُلْ ذَا دَمٍ وَإِنْ تُنْعِمْ تُنْعِمْ عَلَى شَاكِرٍ وَإِنْ كُنْتَ تُرِيدُ الْمَالَ فَسَلْ تُعْطَ مِنْهُ مَا شِئْتَ فَتَرَكَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا كَانَ الْغَدُ قَالَ لَهُ مَا عِنْدَكَ يَا ‏ ‏ثُمَامَةُ ‏ ‏قَالَ مَا قُلْتُ لَكَ إِنْ تُنْعِمْ تُنْعِمْ عَلَى شَاكِرٍ وَإِنْ تَقْتُلْ تَقْتُلْ ذَا دَمٍ وَإِنْ كُنْتَ تُرِيدُ الْمَالَ فَسَلْ تُعْطَ مِنْهُ مَا شِئْتَ ‏ ‏فَتَرَكَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى كَانَ بَعْدَ الْغَدِ فَقَالَ مَا عِنْدَكَ يَا ‏ ‏ثُمَامَةُ ‏ ‏فَقَالَ عِنْدِي مَا قُلْتُ لَكَ إِنْ تُنْعِمْ تُنْعِمْ عَلَى شَاكِرٍ وَإِنْ تَقْتُلْ تَقْتُلْ ذَا دَمٍ وَإِنْ كُنْتَ تُرِيدُ الْمَالَ فَسَلْ تُعْطَ مِنْهُ مَا شِئْتَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْطَلِقُوا ‏ ‏بِثُمَامَةَ ‏ ‏فَانْطَلَقُوا بِهِ إِلَى نَخْلٍ قَرِيبٍ مِنْ الْمَسْجِدِ فَاغْتَسَلَ ثُمَّ دَخَلَ الْمَسْجِدَ فَقَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ يَا ‏ ‏مُحَمَّدُ ‏ ‏وَاللَّهِ مَا كَانَ عَلَى وَجْهٌ الْأَرْضِ أَبْغَضَ إِلَيَّ مِنْ وَجْهِكَ فَقَدْ أَصْبَحَ وَجْهُكَ أَحَبَّ الْوُجُوهِ كُلِّهَا إِلَيَّ وْ وَاللَّهِ مَا كَانَ مِنْ دِينٍ أَبْغَضَ إِلَيَّ مِنْ دِينِكَ فَأَصْبَحَ دِينُكَ أَحَبَّ الْأَدْيَانِ إِلَيَّ وَاللَّهِ مَا كَانَ مِنْ بَلَدٍ أَبْغَضَ إِلَيَّ مِنْ بَلَدِكَ فَأَصْبَحَ بَلَدُكَ أَحَبَّ الْبِلَادِ إِلَيَّ وَإِنَّ خَيْلَكَ أَخَذَتْنِي وَإِنِّي أُرِيدُ الْعُمْرَةَ فَمَاذَا ‏ ‏تَرَى فَبَشَّرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَمَرَهُ أَنْ يَعْتَمِرَ فَلَمَّا قَدِمَ ‏ ‏مَكَّةَ ‏ ‏قَالَ لَهُ قَائِلٌ ‏ ‏صَبَأْتَ ‏ ‏فَقَالَ لَا وَلَكِنْ أَسْلَمْتُ مَعَ ‏ ‏مُحَمَّدٍ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا وَاللَّهِ لَا ‏ ‏يَأْتِيكُمْ مِنْ ‏ ‏الْيَمَامَةِ ‏ ‏حَبَّةُ ‏ ‏حِنْطَةٍ ‏ ‏حَتَّى ‏ ‏يَأْذَنَ ‏ ‏فِيهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[9458,9458,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّهُ سُئِلَ عَنْ الرَّجُلِ يَجْمَعُ بَيْنَ الْمَرْأَةِ وَبَيْنَ خَالَةِ أَبِيهَا وَالْمَرْأَةِ وَخَالَةِ أُمِّهَا أَوْ بَيْنَ الْمَرْأَةِ وَعَمَّةِ أَبِيهَا أَوْ الْمَرْأَةِ وَعَمَّةِ أُمِّهَا ‏ ‏فَقَالَ قَالَ ‏ ‏قَبِيصَةُ بْنُ ذُؤَيْبٍ ‏ ‏سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُجْمَعَ بَيْنَ الْمَرْأَةِ وَخَالَتِهَا وَبَيْنَ الْمَرْأَةِ وَعَمَّتِهَا ‏ ‏فَنَرَى خَالَةَ أُمِّهَا وَعَمَّةَ أُمِّهَا بِتِلْكَ الْمَنْزِلَةِ وَإِنْ كَانَ مِنْ الرَّضَاعِ يَكُونُ مِنْ ذَلِكَ بِتِلْكَ الْمَنْزِلَةِ ‏","","",""],[9459,9459,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّهُ قَالَ أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُقِيمَتْ الصَّلَاةُ فَلَا تَأْتُوهَا ‏ ‏تَسْعَوْنَ ‏ ‏وَأْتُوهَا تَمْشُونَ وَعَلَيْكُمْ ‏ ‏السَّكِينَةُ ‏ ‏فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا فَاتَكُمْ فَأَتِمُّوا ‏","","",""],[9460,9460,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ قَالَ لِصَبِيٍّ تَعَالَ ‏ ‏هَاكَ ثُمَّ لَمْ يُعْطِهِ فَهِيَ كَذْبَةٌ ‏","","",""],[9461,9461,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ وَحَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَنَا أَشْبَهُكُمْ صَلَاةً بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ قَالَ اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ قَالَا وَكَانَ يُكَبِّرُ إِذَا رَكَعَ وَإِذَا قَامَ مِنْ السُّجُودِ وَإِذَا رَفَعَ رَأْسَهُ مِنْ السَّجْدَتَيْنِ ‏","","",""],[9462,9462,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ وَحَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَأْتِيَنَّ عَلَى النَّاسِ زَمَانٌ لَا ‏ ‏يُبَالِي ‏ ‏الْمَرْءُ بِمَا أَخَذَ مِنْ الْمَالِ بِحَلَالٍ أَوْ بِحَرَامٍ ‏","","",""],[9463,9463,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَيَزِيدُ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَمْ يَدَعْ قَوْلَ ‏ ‏الزُّورِ ‏ ‏وَالْعَمَلَ بِهِ وَالْجَهْلَ فَلَيْسَ ‏ ‏لِلَّهِ حَاجَةٌ أَنْ يَدَعَ طَعَامَهُ وَشَرَابَهُ ‏","","",""],[9464,9464,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏لَوْلَا أَمْرَانِ لَأَحْبَبْتُ أَنْ أَكُونَ عَبْدًا مَمْلُوكًا وَذَلِكَ أَنَّ الْمَمْلُوكَ لَا يَسْتَطِيعُ أَنْ يَصْنَعَ فِي مَالِهِ شَيْئًا وَذَلِكَ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا خَلَقَ اللَّهُ عَبْدًا يُؤَدِّي حَقَّ اللَّهِ وَحَقَّ سَيِّدِهِ إِلَّا وَفَّاهُ اللَّهُ أَجْرَهُ مَرَّتَيْنِ ‏","","",""],[9465,9465,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا ‏ ‏يُوطِنُ ‏ ‏رَجُلٌ مُسْلِمٌ الْمَسَاجِدَ لِلصَّلَاةِ وَالذِّكْرِ إِلَّا ‏ ‏تَبَشْبَشَ ‏ ‏اللَّهُ بِهِ ‏ ‏يَعْنِي حِينَ يَخْرُجُ مِنْ بَيْتِهِ كَمَا ‏ ‏يَتَبَشْبَشُ ‏ ‏أَهْلُ الْغَائِبِ بِغَائِبِهِمْ إِذَا قَدِمَ عَلَيْهِمْ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[9466,9466,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَحَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا جَلَسَ قَوْمٌ مَجْلِسًا لَمْ يَذْكُرُوا اللَّهَ فِيهِ وَلَمْ يُصَلُّوا عَلَى نَبِيِّهِمْ إِلَّا كَانَ عَلَيْهِمْ ‏ ‏تِرَةً ‏","","",""],[9467,9467,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بُكَيْرُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ ‏ ‏قَالَ بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْثٍ وَقَالَ إِنْ وَجَدْتُمْ ‏ ‏فُلَانًا ‏ ‏وَفُلَانًا ‏ ‏لِرَجُلَيْنِ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَأَحْرِقُوهُمَا بِالنَّارِ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَرَدْنَا الْخُرُوجَ ‏ ‏إِنِّي كُنْتُ أَمَرْتُكُمْ أَنْ تُحْرِقُوا ‏ ‏فُلَانًا ‏ ‏وَفُلَانًا ‏ ‏بِالنَّارِ وَإِنَّ النَّارَ لَا يُعَذِّبُ بِهَا إِلَّا اللَّهُ فَإِنْ وَجَدْتُمُوهُمَا فَاقْتُلُوهُمَا ‏","","",""],[9468,9468,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏وَسَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَتَى ‏ ‏رَجُلٌ ‏ ‏مِنْ الْمُسْلِمِينَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي الْمَسْجِدِ فَنَادَاهُ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي زَنَيْتُ فَأَعْرَضَ عَنْهُ ‏ ‏فَتَنَحَّى ‏ ‏تِلْقَاءَ ‏ ‏وَجْهِهِ فَقَالَ لَهُ يَا رَسُولَ اللَّهِ إِنِّي زَنَيْتُ فَأَعْرَضَ عَنْهُ حَتَّى ثَنَّى ذَلِكَ عَلَيْهِ أَرْبَعَ مَرَّاتٍ ‏ ‏فَلَمَّا شَهِدَ عَلَى نَفْسِهِ أَرْبَعَ مَرَّاتٍ دَعَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَبِكَ جُنُونٌ قَالَ لَا قَالَ فَهَلْ ‏ ‏أَحْصَنْتَ ‏ ‏قَالَ نَعَمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اذْهَبُوا بِهِ ‏ ‏فَارْجُمُوهُ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏فَأَخْبَرَنِي ‏ ‏مَنْ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏كُنْتُ فِيمَنْ ‏ ‏رَجَمَهُ ‏ ‏فَرَجَمْنَاهُ ‏ ‏فِي الْمُصَلَّى فَلَمَّا ‏ ‏أَذْلَقَتْهُ ‏ ‏الْحِجَارَةُ هَرَبَ فَأَدْرَكْنَاهُ ‏ ‏بِالْحَرَّةِ ‏ ‏فَرَجَمْنَاهُ ‏","","",""],[9469,9469,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏قَضَى ‏ ‏فِيمَنْ زَنَى وَلَمْ ‏ ‏يُحْصِنْ ‏ ‏أَنْ ‏ ‏يُنْفَى عَامًا مَعَ ‏ ‏الْحَدِّ ‏ ‏عَلَيْهِ ‏","","",""],[9470,9470,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَانَ يَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا ‏","","",""],[9471,9471,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُؤْتَى بِالرَّجُلِ الْمُتَوَفَّى عَلَيْهِ دَيْنٌ فَيَسْأَلُ هَلْ تَرَكَ لِذَلِكَ مِنْ ‏ ‏قَضَاءٍ ‏ ‏فَإِنْ قَالُوا نَعَمْ إِنَّهُ تَرَكَ وَفَاءً صَلَّى عَلَيْهِ وَإِلَّا قَالَ لِلْمُسْلِمِينَ صَلُّوا عَلَى صَاحِبِكُمْ فَلَمَّا فَتَحَ اللَّهُ عَلَيْهِ الْفُتُوحَ قَامَ فَقَالَ ‏ ‏أَنَا أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ فَمَنْ تُوُفِّيَ مِنْ الْمُؤْمِنِينَ فَتَرَكَ دَيْنًا فَعَلَيَّ قَضَاؤُهُ وَمَنْ تَرَكَ مَالًا فَهُوَ لِوَرَثَتِهِ ‏","","",""],[9472,9472,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا ‏ ‏طِيَرَةَ ‏ ‏وَخَيْرُهَا الْفَأْلُ قِيلَ يَا رَسُولَ اللَّهِ وَمَا الْفَأْلُ قَالَ كَلِمَةٌ صَالِحَةٌ يَسْمَعُهَا أَحَدُكُمْ ‏","","",""],[9473,9473,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَاتَلَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏","","",""],[9474,9474,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّهُ قَالَ أَخْبَرَنِي ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ إِلَى الصَّلَاةِ يُكَبِّرُ حِينَ يَقُومُ ثُمَّ يُكَبِّرُ حِينَ يَرْكَعُ ثُمَّ يَقُولُ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ حِينَ يَرْفَعُ ‏ ‏صُلْبَهُ ‏ ‏مِنْ الرَّكْعَةِ ثُمَّ يَقُولُ وَهُوَ قَائِمٌ رَبَّنَا لَكَ الْحَمْدُ ثُمَّ يُكَبِّرُ حِينَ يَهْوِي سَاجِدًا ثُمَّ يُكَبِّرُ حِينَ يَرْفَعُ رَأْسَهُ ثُمَّ يُكَبِّرُ حِينَ يَهْوِي سَاجِدًا ثُمَّ يُكَبِّرُ حِينَ يَرْفَعُ رَأْسَهُ ثُمَّ يَفْعَلُ ذَلِكَ فِي الصَّلَاةِ كُلِّهَا حَتَّى يَقْضِيَهَا وَيُكَبِّرُ حِينَ يَقُومُ مِنْ اللَّتَيْنِ بَعْدَ الْجُلُوسِ ‏","","",""],[9475,9475,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏عَنِ ‏ ‏ابْنِ دَارَّةَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏قَالَ ‏ ‏إِنَّا ‏ ‏لَبِالْبَقِيعِ ‏ ‏مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏إِذْ سَمِعْنَاهُ يَقُولُ أَنَا أَعْلَمُ النَّاسِ بِشَفَاعَةِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْقِيَامَةِ قَالَ فَتَدَاكَّ النَّاسُ عَلَيْهِ فَقَالُوا إِيهٍ يَرْحَمُكَ اللَّهُ قَالَ يَقُولُ ‏ ‏اللَّهُمَّ اغْفِرْ لِكُلِّ عَبْدٍ مُسْلِمٍ لَقِيَكَ مُؤْمِنٌ بِي لَا يُشْرِكُ بِكَ ‏","","",""],[9476,9476,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَعُدُّوا ثَلَاثِينَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَذَكَرَهُ ‏","","",""],[9477,9477,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ جَرَّ ‏ ‏إِزَارَهُ ‏ ‏بَطَرًا ‏ ‏فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَنْظُرُ إِلَيْهِ ‏","","",""],[9478,9478,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏بُدَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَتَعَوَّذُ بِاللَّهِ مِنْ عَذَابِ الْقَبْرِ وَمِنْ عَذَابِ جَهَنَّمَ وَمِنْ ‏ ‏فِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏","","",""],[9479,9479,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَيُذَادَنَّ ‏ ‏نَاسٌ مِنْ أَصْحَابِي عَنْ الْحَوْضِ كَمَا ‏ ‏تُذَادُ ‏ ‏الْغَرِيبَةُ مِنْ الْإِبِلِ ‏","","",""],[9480,9480,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ جُحَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ كَسْبِ الْإِمَاءِ ‏","","",""],[9481,9481,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَجْمَاءُ ‏ ‏جَرْحُهَا ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏مَا سَمِعْتُ أَحَدًا يَقُولُ ‏ ‏الرَّكَائِزَ ‏ ‏غَيْرَهُ ‏","","",""],[9482,9482,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏سَجَدَ فِي ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏","","",""],[9483,9483,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏تَفْضُلُ صَلَاةُ الْجَمَاعَةِ عَلَى صَلَاةِ الْوَحْدَةِ سَبْعًا وَعِشْرِينَ دَرَجَةً ‏ ‏أَوْ خَمْسًا وَعِشْرِينَ دَرَجَةً ‏","","",""],[9484,9484,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ ‏ ‏الْخَلَاءَ ‏ ‏دَعَا بِمَاءٍ ‏ ‏فَاسْتَنْجَى ‏ ‏ثُمَّ مَسَحَ ‏ ‏بِيَدِهِ ‏ ‏عَلَى الْأَرْضِ ثُمَّ تَوَضَّأَ ‏","","",""],[9485,9485,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ غَسَّلَ مَيِّتًا فَلْيَغْتَسِلْ وَمَنْ حَمَلَهُ فَلْيَتَوَضَّأْ ‏","","",""],[9486,9486,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سَلْمِ بْنِ عَبْدِ الرَّحْمَنِ النَّخَعِيِّ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ تَسَمَّى بِاسْمِي فَلَا ‏ ‏يَتَكَنَّى بِكُنْيَتِي وَمَنْ تَكَنَّى بِكُنْيَتِي فَلَا ‏ ‏يَتَسَمَّى بِاسْمِي ‏ ‏حَدَّثَنَاه ‏ ‏أَسْوَدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[9487,9487,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى عَلَى جَنَازَةٍ فِي الْمَسْجِدِ فَلَا شَيْءَ لَهُ ‏","","",""],[9488,9488,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عِرَاكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ ‏ ‏مِنْ شِرَارِ النَّاسِ ذَا الْوَجْهَيْنِ الَّذِي يَأْتِي هَؤُلَاءِ بِوَجْهٍ وَهَؤُلَاءِ بِوَجْهٍ ‏","","",""],[9489,9489,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏بُعِثْتُ ‏ ‏بِجَوَامِعِ الْكَلِمِ ‏ ‏وَنُصِرْتُ ‏ ‏بِالرُّعْبِ ‏ ‏وَبَيْنَمَا أَنَا نَائِمٌ أُتِيتُ بِمَفَاتِيحِ خَزَائِنِ الْأَرْضِ فَوُضِعَتْ فِي يَدَيَّ ‏","","",""],[9490,9490,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَنْ يَحْتَزِمَ أَحَدُكُمْ حُزْمَةَ حَطَبٍ فَيَحْمِلَهَا عَلَى ظَهْرِهِ فَيَبِيعَهَا خَيْرٌ لَهُ مِنْ أَنْ يَسْأَلَ رَجُلًا يُعْطِيهِ أَوْ يَمْنَعُهُ ‏","","",""],[9491,9491,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ مَنَامِهِ فَلَا يَغْمِسْ يَدَهُ فِي إِنَائِهِ حَتَّى يَغْسِلَهَا ثَلَاثًا فَإِنَّهُ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ مِنْهُ ‏","","",""],[9492,9492,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الضَّحَّاكِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ إِنَّ ‏ ‏فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا سَبْعِينَ ‏ ‏أَوْ مِائَةَ سَنَةٍ ‏ ‏هِيَ شَجَرَةُ الْخُلْدِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏أَوْ مِائَةَ سَنَةٍ شَجَرَةُ الْخُلْدِ ‏ ‏قُلْتُ ‏ ‏لِشُعْبَةَ ‏ ‏هِيَ شَجَرَةُ الْخُلْدِ قَالَ لَيْسَ فِيهَا هِيَ ‏","","",""],[9493,9493,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏وَعَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ عَبْدِ الْجَبَّارِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ إِنَّ الرَّحِمَ ‏ ‏شُجْنَةٌ ‏ ‏مِنْ الرَّحْمَنِ تَقُولُ يَا رَبِّ إِنِّي قُطِعْتُ يَا رَبِّ إِنِّي ظُلِمْتُ يَا رَبِّ إِنِّي أُسِيءَ إِلَيَّ يَا رَبِّ يَا رَبِّ فَيُجِيبُهَا رَبُّهَا عَزَّ وَجَلَّ فَيَقُولُ ‏ ‏أَمَا تَرْضَيْنَ أَنْ أَصِلَ مَنْ وَصَلَكِ وَأَقْطَعَ مَنْ قَطَعَكِ ‏ ‏حَدَّثَنَاه ‏ ‏أَبُو الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الْجَبَّارِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ كَعْبٍ الْقُرَظِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏ذَلِكَ ‏","","",""],[9494,9494,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏أَبِي الرَّبِيعِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَرْبَعٌ فِي أُمَّتِي مِنْ أَمْرِ الْجَاهِلِيَّةِ لَنْ يَدَعُوهُنَّ ‏ ‏التَّطَاعُنُ ‏ ‏فِي الْأَنْسَابِ ‏ ‏وَالنِّيَاحَةُ ‏ ‏وَمُطِرْنَا ‏ ‏بِنَوْءِ ‏ ‏كَذَا وَكَذَا ‏ ‏وَالْعَدْوَى ‏ ‏الرَّجُلُ يَشْتَرِي الْبَعِيرَ الْأَجْرَبَ فَيَجْعَلُهُ فِي مِائَةِ بَعِيرٍ فَتَجْرَبُ فَمَنْ أَعْدَى الْأَوَّلَ ‏","","",""],[9495,9495,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَرْقَاءَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا أُقِيمَتْ الصَّلَاةُ فَلَا صَلَاةَ إِلَّا الْمَكْتُوبَةَ ‏","","",""],[9496,9496,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا حَازِمٍ ‏ ‏الْمَعْنَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ كَافِرٌ فَكَانَ يَأْكُلُ أَكْلًا كَثِيرًا ثُمَّ إِنَّهُ أَسْلَمَ فَكَانَ يَأْكُلُ أَكْلًا قَلِيلًا فَذُكِرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ ‏ ‏الْكَافِرَ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ وَإِنَّ الْمُسْلِمَ يَأْكُلُ فِي مِعًى وَاحِدٍ ‏","","",""],[9497,9497,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ تَرَكَ مَالًا فَلِوَرَثَتِهِ وَمَنْ تَرَكَ كَلًّا وُلِّيتُهُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏وَمَنْ تَرَكَ كَلًّا فَإِلَيْنَا ‏","","",""],[9498,9498,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُمْ قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ أَحَدَنَا يُحَدِّثُ نَفْسَهُ بِالشَّيْءِ مَا يُحِبُّ أَنَّهُ يَتَكَلَّمُ بِهِ وَإِنَّ لَهُ مَا عَلَى الْأَرْضِ مِنْ شَيْءٍ قَالَ ذَاكَ ‏ ‏مَحْضُ ‏ ‏الْإِيمَانِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏بِإِسْنَادِهِ قَالَ ‏ ‏مِنْ شَأْنِ الرَّبِّ عَزَّ وَجَلَّ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَلْقَمَةُ بْنُ مَرْثَدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الرَّبِيعِ ‏ ‏وَكَانَ يُقَاعِدُ ‏ ‏أَبَا بُرْدَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَرْبَعٌ فِي أُمَّتِي ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏نَحْوَ حَدِيثِ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرٍ ‏","","",""],[9499,9499,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَرْوَانَ الْأَصْغَرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا رَافِعٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏سَجَدَ فِي ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏قَالَ فَسَأَلْتُهُ فَقَالَ سَجَدَ فِيهَا خَلِيلِي وَلَا أَزَالُ أَسْجُدُ حَتَّى أَلْقَاهُ ‏","","",""],[9500,9500,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ لِرَجُلٍ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَقٌّ فَأَغْلَظَ لَهُ فَهَمَّ بِهِ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنَّ لِصَاحِبِ الْحَقِّ مَقَالًا وَقَالَ لَهُمْ اشْتَرُوا لَهُ ‏ ‏سِنًّا ‏ ‏فَأَعْطُوهُ فَقَالُوا إِنَّا لَا نَجِدُ إِلَّا ‏ ‏سِنًّا ‏ ‏أَفْضَلَ مِنْ ‏ ‏سِنِّهِ ‏ ‏فَقَالَ اشْتَرُوا لَهُ فَأَعْطُوهُ فَقَالَ ‏ ‏إِنَّ مِنْ خَيْرِكُمْ ‏ ‏أَوْ خَيْرُكُمْ ‏ ‏أَحْسَنَكُمْ قَضَاءً ‏","","",""],[9501,9501,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏رَفَعَهُ مَرَّةً ثُمَّ لَمْ يَرْفَعْهُ بَعْدُ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا هِجْرَةَ بَعْدَ ثَلَاثٍ ‏ ‏أَوْ فَوْقَ ثَلَاثٍ ‏ ‏فَمَنْ هَاجَرَ بَعْدَ ثَلَاثٍ ‏ ‏أَوْ فَوْقَ ثَلَاثٍ ‏ ‏فَمَاتَ دَخَلَ النَّارَ ‏","","",""],[9502,9502,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعَجْمَاءُ ‏ ‏جَرْحُهَا ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏","","",""],[9503,9503,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ زِيَادٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَدْخُلُ الْجَنَّةَ مِنْ أُمَّتِي سَبْعُونَ أَلْفًا بِغَيْرِ حِسَابٍ قَالَ فَقَالَ ‏ ‏عُكَّاشَةُ ‏ ‏يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ اجْعَلْهُ مِنْهُمْ قَالَ فَقَامَ رَجُلٌ آخَرُ فَقَالَ يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ فَقَالَ سَبَقَكَ بِهَا ‏ ‏عُكَّاشَةُ ‏","","",""],[9504,9504,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏أَوْ قَالَ قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏أَمَا ‏ ‏يَخْشَى أَلَا ‏ ‏يَخْشَى أَحَدُكُمْ أَنْ يَجْعَلَ اللَّهُ رَأْسَهُ رَأْسَ حِمَارٍ أَوْ صُورَتَهُ صُورَةَ حِمَارٍ إِذَا رَفَعَ رَأْسَهُ قَبْلَ الْإِمَامِ وَالْإِمَامُ سَاجِدٌ ‏","","",""],[9505,9505,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَصُومُوا حَتَّى تَرَوْا الْهِلَالَ وَلَا تُفْطِرُوا حَتَّى تَرَوْا الْهِلَالَ وَقَالَ صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ ‏ ‏غَبِيَ ‏ ‏عَلَيْكُمْ فَعُدُّوا ثَلَاثِينَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأَكْثَرُ عِلْمِي أَنَّهُ قَالَ لَا تَصُومُوا حَتَّى تَرَوْا الْهِلَالَ وَلَا تُفْطِرُوا حَتَّى تَرَوْا الْهِلَالَ ‏","","",""],[9506,9506,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏أَنَّهُ قَالَ ‏ ‏بَيْنَمَا رَجُلٌ يَمْشِي وَعَلَيْهِ ‏ ‏حُلَّةٌ ‏ ‏مُرَجِّلًا ‏ ‏جُمَّتَهُ ‏ ‏تُعْجِبُهُ نَفْسُهُ إِذْ خُسِفَ بِهِ فَهُوَ ‏ ‏يَتَجَلْجَلُ ‏ ‏فِي الْأَرْضِ إِلَى يَوْمِ الْقِيَامَةِ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏إِذْ خَسَفَ اللَّهُ بِهِ ‏","","",""],[9507,9507,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ذَرُونِي ‏ ‏مَا تَرَكْتُكُمْ فَإِنَّمَا أُهْلِكَ ‏ ‏أَهْلُ الْكِتَابِ ‏ ‏قَبْلَكُمْ ‏ ‏أَوْ مَنْ كَانَ قَبْلَكُمْ ‏ ‏بِكَثْرَةِ اخْتِلَافِهِمْ عَلَى أَنْبِيَائِهِمْ وَكَثْرَةِ سُؤَالِهِمْ فَانْظُرُوا مَا أَمَرْتُكُمْ بِهِ فَاتَّبِعُوهُ مَا اسْتَطَعْتُمْ وَمَا نَهَيْتُكُمْ عَنْهُ فَدَعُوهُ ‏ ‏أَوْ ذَرُوهُ ‏","","",""],[9508,9508,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْوِيهِ عَنْ رَبِّكُمْ عَزَّ وَجَلَّ ‏ ‏كُلُّ الْعَمَلِ ‏ ‏كَفَّارَةٌ ‏ ‏وَالصَّوْمُ لِي وَأَنَا ‏ ‏أَجْزِي ‏ ‏بِهِ ‏ ‏وَلَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ ‏ ‏الْمِسْكِ ‏","","",""],[9509,9509,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَجِبَ اللَّهُ مِنْ أَقْوَامٍ يُجَاءُ بِهِمْ فِي السَّلَاسِلِ حَتَّى يَدْخُلُوا الْجَنَّةَ ‏","","",""],[9510,9510,"","","‏ ‏وَبِالْإِسْنَادِ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَيْسَ الْمِسْكِينُ الَّذِي تَرُدُّهُ الْأُكْلَةُ وَالْأُكْلَتَانِ وَاللُّقْمَةُ وَاللُّقْمَتَانِ ‏ ‏أَوْ التَّمْرَةُ وَالتَّمْرَتَانِ ‏ ‏شُعْبَةُ ‏ ‏شَكَّ فِي اللُّقْمَةِ وَالتَّمْرَةِ ‏ ‏وَلَكِنَّ الْمِسْكِينَ الَّذِي لَيْسَ لَهُ غِنًى يُغْنِيهِ وَلَا يَسْأَلُ النَّاسَ ‏ ‏إِلْحَافًا ‏ ‏أَوْ يَسْتَحِي أَنْ يَسْأَلَ النَّاسَ ‏ ‏إِلْحَافًا ‏","","",""],[9511,9511,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏دَخَلَتْ النَّارَ امْرَأَةٌ فِي هِرَّةٍ رَبَطَتْهَا وَلَمْ تَدَعْهَا تَأْكُلُ مِنْ ‏ ‏خَشَاشِ ‏ ‏الْأَرْضِ ‏","","",""],[9512,9512,"","","‏ ‏وَبِالْإِسْنَادِ ‏ ‏إِنَّ ‏ ‏فِي الْجُمُعَةِ لَسَاعَةً لَا ‏ ‏يُوَافِقُهَا ‏ ‏عَبْدٌ مُسْلِمٌ يَسْأَلُ اللَّهَ عَزَّ وَجَلَّ فِيهَا خَيْرًا إِلَّا أَعْطَاهُ إِيَّاهُ ‏","","",""],[9513,9513,"","","‏ ‏وَبِالْإِسْنَادِ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا أُحِبُّ أَنَّ لِي مِثْلَ ‏ ‏أُحُدٍ ‏ ‏ذَهَبًا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَوْ قَالَ مَا أُحِبُّ أَنَّ لِي ‏ ‏أُحُدًا ‏ ‏ذَهَبًا ‏ ‏أَدَعُ ‏ ‏يَوْمَ أَمُوتُ دِينَارًا إِلَّا أَنْ ‏ ‏أُرْصِدَهُ ‏ ‏لِدَيْنٍ ‏","","",""],[9514,9514,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ النَّخَعِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا زُرْعَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏","","",""],[9515,9515,"","","‏ ‏قَالَ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكْرَهُ ‏ ‏الشِّكَالَ ‏ ‏مِنْ الْخَيْلِ ‏ ‏أَوْ الْأَشْكَالَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏شُعْبَةُ ‏ ‏يُخْطِئُ فِي هَذَا الْقَوْلِ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ ‏ ‏وَإِنَّمَا هُوَ ‏ ‏سَلْمُ بْنُ عَبْدِ الرَّحْمَنِ النَّخَعِيُّ ‏","","",""],[9516,9516,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَلَاءَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْإِيمَانُ يَمَانٍ وَالْكُفْرُ مِنْ قِبَلِ الْمَشْرِقِ وَإِنَّ ‏ ‏السَّكِينَةَ ‏ ‏فِي أَهْلِ الْغَنَمِ وَإِنَّ ‏ ‏الرِّيَاءَ ‏ ‏وَالْفَخْرَ فِي أَهْلِ ‏ ‏الْفَدَّادِينَ ‏ ‏أَهْلِ ‏ ‏الْوَبَرِ ‏ ‏وَأَهْلِ الْخَيْلِ وَيَأْتِي ‏ ‏الْمَسِيحُ ‏ ‏مِنْ قِبَلِ الْمَشْرِقِ وَهِمَّتُهُ ‏ ‏الْمَدِينَةُ ‏ ‏حَتَّى إِذَا جَاءَ ‏ ‏دُبُرَ ‏ ‏أُحُدٍ ‏ ‏تَلَقَّتْهُ الْمَلَائِكَةُ فَضَرَبَتْ وَجْهَهُ قِبَلَ ‏ ‏الشَّامِ ‏ ‏هُنَالِكَ يُهْلَكُ هُنَالِكَ يُهْلَكُ ‏","","",""],[9517,9517,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَلَاءَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا تَطْلُعُ الشَّمْسُ بِيَوْمٍ وَلَا تَغْرُبُ بِأَفْضَلَ ‏ ‏أَوْ أَعْظَمَ ‏ ‏مِنْ يَوْمِ الْجُمُعَةِ وَمَا مِنْ دَابَّةٍ إِلَّا تَفْزَعُ لِيَوْمِ الْجُمُعَةِ إِلَّا هَذَانِ الثَّقَلَانِ مِنْ الْجِنِّ وَالْإِنْسِ وَعَلَى كُلِّ بَابٍ مَلَكَانِ يَكْتُبَانِ الْأَوَّلَ فَالْأَوَّلَ كَرَجُلٍ قَدَّمَ ‏ ‏بَدَنَةً ‏ ‏وَكَرَجُلٍ قَدَّمَ بَقَرَةً وَكَرَجُلٍ قَدَّمَ شَاةً وَكَرَجُلٍ قَدَّمَ طَيْرًا وَكَرَجُلٍ قَدَّمَ بَيْضَةً فَإِذَا قَعَدَ الْإِمَامُ طُوِيَتْ الصُّحُفُ ‏","","",""],[9518,9518,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَلَاءَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَظْهَرَ ثَلَاثُونَ دَجَّالُونَ كُلُّهُمْ يَزْعُمُ أَنَّهُ رَسُولُ اللَّهِ ‏ ‏وَيَفِيضَ ‏ ‏الْمَالُ فَيَكْثُرَ وَتَظْهَرَ ‏ ‏الْفِتَنُ ‏ ‏وَيَكْثُرَ ‏ ‏الْهَرْجُ ‏ ‏قَالَ قِيلَ وَأَيُّمَا ‏ ‏الْهَرْجُ ‏ ‏قَالَ الْقَتْلُ الْقَتْلُ ثَلَاثًا ‏","","",""],[9519,9519,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَلَاءَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُلُّ صَلَاةٍ لَا يُقْرَأُ فِيهَا ‏ ‏بِأُمِّ الْكِتَابِ ‏ ‏فَهِيَ ‏ ‏خِدَاجٌ ‏ ‏فَهِيَ ‏ ‏خِدَاجٌ ‏ ‏فَهِيَ ‏ ‏خِدَاجٌ ‏ ‏غَيْرُ تَمَامٍ ‏","","",""],[9520,9520,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَلَاءَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏يَسْتَامُ ‏ ‏الرَّجُلُ عَلَى ‏ ‏سَوْمِ ‏ ‏أَخِيهِ وَلَا يَخْطُبُ عَلَى خِطْبَتِهِ ‏","","",""],[9521,9521,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا دَعَا أَحَدُكُمْ فَلَا يَقُولَنَّ اللَّهُمَّ إِنْ شِئْتَ وَلَكِنْ ‏ ‏لِيُعْظِمْ رَغْبَتَهُ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَتَعَاظَمُ عَلَيْهِ شَيْءٌ أَعْطَاهُ ‏","","",""],[9522,9522,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَلَاءَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ تَدْرُونَ مَا الْغِيَابَةُ قَالَ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏ذِكْرُكَ أَخَاكَ بِمَا لَيْسَ فِيهِ قَالَ أَرَأَيْتَ إِنْ كَانَ فِي أَخِي مَا أَقُولُ لَهُ قَالَ إِنْ كَانَ فِيهِ مَا تَقُولُ فَقَدْ ‏ ‏اغْتَبْتَهُ ‏ ‏وَإِنْ لَمْ يَكُنْ فِيهِ مَا تَقُولُ فَقَدْ ‏ ‏بَهَتَّهُ ‏","","",""],[9523,9523,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي الْحَارِثِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏مَا أَنَا أَنْهَاكُمْ أَنْ تَصُومُوا يَوْمَ الْجُمُعَةِ وَلَكِنْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَصُومُوا يَوْمَ الْجُمُعَةِ إِلَّا أَنْ تَصُومُوا قَبْلَهُ وَمَا أَنَا أُصَلِّي فِي نَعْلَيْنِ وَلَكِنْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي نَعْلَيْنِ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏زِيَادٍ الْحَارِثِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَجُلًا يَسْأَلُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[9524,9524,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَالِمًا الْبَرَّادَ أَبَا عَبْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَبِعَ جَنَازَةً فَصَلَّى عَلَيْهَا ‏ ‏أَوْ قَالَ مَنْ صَلَّى عَلَيْهَا ‏ ‏شُعْبَةُ ‏ ‏شَكَّ ‏ ‏فَلَهُ قِيرَاطٌ فَإِنْ شَهِدَ دَفْنَهَا فَلَهُ قِيرَاطَانِ الْقِيرَاطُ مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[9525,9525,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ أَصْدَقَ بَيْتٍ قَالَتْهُ الشُّعَرَاءُ ‏ ‏أَلَا كُلُّ شَيْءٍ مَا ‏ ‏خَلَا ‏ ‏اللَّهَ بَاطِلُ ‏","","",""],[9526,9526,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عُثْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا يَحْيَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُؤَذِّنُ يُغْفَرُ لَهُ ‏ ‏مَدَّ ‏ ‏صَوْتِهِ وَيَشْهَدُ لَهُ كُلُّ رَطْبٍ وَيَابِسٍ وَشَاهِدُ الصَّلَاةِ يُكْتَبُ لَهُ خَمْسٌ وَعِشْرُونَ حَسَنَةً وَيُكَفَّرُ عَنْهُ مَا بَيْنَهُمَا ‏","","",""],[9527,9527,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ حَفْصٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَغَرَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏تَوَضَّئُوا مِمَّا أَنْضَجَتْ النَّارُ ‏","","",""],[9528,9528,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَارَةَ بْنَ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُطَوِّسِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَقَالَ ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُطَوِّسِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ أَفْطَرَ يَوْمًا فِي رَمَضَانَ مِنْ غَيْرِ رُخْصَةٍ رَخَّصَهَا اللَّهُ لَمْ يَقْضِ عَنْهُ صِيَامُ الدَّهْرِ ‏","","",""],[9529,9529,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ خُمَيْرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَوْلًى لِقُرَيْشٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ بَيْعِ الْمَغَانِمِ حَتَّى تُقْسَمَ ‏ ‏ثُمَّ قَالَ بَعْدَ ‏ ‏يَزِيدَ بْنِ خُمَيْرٍ ‏ ‏وَيَعْلَمُ مَا هِيَ قَالَهَا ‏ ‏يَزِيدُ ‏ ‏آخِرَ مَرَّةٍ ‏ ‏وَعَنْ بَيْعِ الثَّمَرِ حَتَّى ‏ ‏يُحْرَزَ ‏ ‏مِنْ كُلِّ ‏ ‏عَارِضٍ ‏ ‏وَأَنْ لَا يُصَلِّيَ الرَّجُلُ إِلَّا وَهُوَ ‏ ‏مُحْتَزِمٌ ‏","","",""],[9530,9530,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ فَرَاهِيجَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَوْصَانِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ يُوَرِّثُهُ ‏","","",""],[9531,9531,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ فَرَاهِيجَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏مَا كَانَ لَنَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَعَامٌ إِلَّا الْأَسْوَدَانِ التَّمْرُ وَالْمَاءُ ‏","","",""],[9532,9532,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَعْنِي اللَّهَ يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏الصَّوْمُ هُوَ لِي وَأَنَا أَجْزِي بِهِ ‏ ‏وَلَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ ‏ ‏الْمِسْكِ ‏","","",""],[9533,9533,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْجُلَاسِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُثْمَانَ بْنَ شَمَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مَرْوَانُ ‏ ‏يَمُرُّ عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ فَيَمُرُّ ‏ ‏بِأَبِي هُرَيْرَةَ ‏ ‏وَهُوَ يُحَدِّثُ فَقَالَ بَعْضَ حَدِيثِكَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ثُمَّ مَضَى قَالَ ‏ ‏ثُمَّ رَجَعَ فَقَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَيْفَ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى الْجِنَازَةِ قَالَ قَالَ ‏ ‏خَلَقْتَهَا ‏ ‏أَوْ قَالَ أَنْتَ خَلَقْتَهَا ‏ ‏شُعْبَةُ ‏ ‏الَّذِي شَكَّ ‏ ‏وَهَدَيْتَهَا إِلَى الْإِسْلَامِ وَأَنْتَ قَبَضْتَ رُوحَهَا تَعْلَمُ سِرَّهَا وَعَلَانِيَتَهَا جِئْنَا ‏ ‏شُفَعَاءَ ‏ ‏فَاغْفِرْ لَهَا ‏","","",""],[9534,9534,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا رَافِعٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏زَيْنَبَ ‏ ‏كَانَ اسْمُهَا ‏ ‏بَرَّةَ ‏ ‏فَقِيلَ تُزَكِّي نَفْسَهَا ‏ ‏فَسَمَّاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَيْنَبَ ‏","","",""],[9535,9535,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَسْجُدُ فِي ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏فَقُلْتُ أَتَسْجُدُ فِيهَا فَقَالَ نَعَمْ رَأَيْتُ خَلِيلِي يَسْجُدُ فِيهَا وَلَا أَزَالُ أَسْجُدُ فِيهَا حَتَّى أَلْقَاهُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قُلْتُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏","","",""],[9536,9536,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَأَبُو دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبَّاسٍ يَعْنِي الْجُرَيْرِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عُثْمَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَوْصَانِي ‏ ‏خَلِيلِي ‏ ‏بِثَلَاثٍ ‏ ‏الْوَتْرِ ‏ ‏قَبْلَ النَّوْمِ وَرَكْعَتَيْ الضُّحَى وَصَوْمِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ ‏","","",""],[9537,9537,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي شِمْرٍ الضُّبَعِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عُثْمَانَ النَّهْدِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَوْصَانِي ‏ ‏خَلِيلِي ‏ ‏بِثَلَاثٍ ‏ ‏الْوَتْرِ ‏ ‏قَبْلَ النَّوْمِ وَرَكْعَتَيْ الضُّحَى وَصَوْمِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ ‏","","",""],[9538,9538,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ أَدْرَكَ رَكْعَةً مِنْ صَلَاةِ الصُّبْحِ قَبْلَ طُلُوعِ الشَّمْسِ فَقَدْ أَدْرَكَ الصَّلَاةَ وَمَنْ أَدْرَكَ رَكْعَتَيْنِ مِنْ الْعَصْرِ قَبْلَ أَنْ تَغِيبَ الشَّمْسُ فَقَدْ أَدْرَكَ الصَّلَاةَ ‏","","",""],[9539,9539,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏لَا تَبْدَءُوهُمْ بِالسَّلَامِ وَإِذَا لَقِيتُمُوهُمْ فِي طَرِيقٍ فَاضْطَرُّوهُمْ إِلَى أَضْيَقِهَا ‏","","",""],[9540,9540,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَثَلُ الْمُجَاهِدِ فِي سَبِيلِ اللَّهِ مَثَلُ الْقَائِمِ لَا ‏ ‏يَفْتُرُ ‏ ‏وَمَثَلُ الصَّائِمِ لَا يُفْطِرُ حَتَّى يَرْجِعَ الْمُجَاهِدُ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[9541,9541,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏وَعَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُمَا أَخْبَرَاهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏أَمَّنَ ‏ ‏الْقَارِئُ فَأَمِّنُوا فَإِنَّهُ مَنْ وَافَقَ تَأْمِينُهُ تَأْمِينَ الْمَلَائِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[9542,9542,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَالَ الْإِمَامُ ‏ { ‏غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ‏} ‏فَقُولُوا آمِينَ فَإِنَّهُ مَنْ وَافَقَ قَوْلُهُ قَوْلَ الْمَلَائِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[9543,9543,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ يَعْنِي ابْنَ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَالَ الْإِمَامُ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ فَإِنَّهُ مَنْ وَافَقَ قَوْلُهُ قَوْلَ الْمَلَائِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[9544,9544,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَالَ أَحَدُكُمْ آمِينَ قَالَتْ الْمَلَائِكَةُ فِي السَّمَاءِ آمِينَ فَوَافَقَتْ إِحْدَاهُمَا الْأُخْرَى غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[9545,9545,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏فِي حَدِيثِ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏مَوْلَى ‏ ‏ابْنِ أَبِي أَحْمَدَ ‏ ‏أَنَّهُ قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْعَصْرِ فَسَلَّمَ مِنْ ‏ ‏رَكْعَتَيْنِ فَقَامَ ‏ ‏ذُو الْيَدَيْنِ ‏ ‏فَقَالَ أَقَصُرَتْ الصَّلَاةُ يَا رَسُولَ اللَّهِ أَمْ نَسِيتَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ ذَلِكَ لَمْ يَكُنْ فَقَالَ قَدْ كَانَ ذَلِكَ يَا رَسُولَ اللَّهِ فَأَقْبَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى النَّاسِ فَقَالَ أَصَدَقَ ‏ ‏ذُو الْيَدَيْنِ ‏ ‏فَقَالُوا نَعَمْ ‏ ‏فَأَتَمَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بَقِيَ مِنْ صَلَاتِهِ ثُمَّ سَجَدَ سَجْدَتَيْنِ وَهُوَ جَالِسٌ ‏","","",""],[9546,9546,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اغْتَسَلَ يَوْمَ الْجُمُعَةِ ‏ ‏فِي حَدِيثِ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏غُسْلَ ‏ ‏الْجَنَابَةِ ‏ ‏ثُمَّ رَاحَ فَكَأَنَّمَا قَرَّبَ ‏ ‏بَدَنَةً ‏ ‏وَمَنْ رَاحَ فِي السَّاعَةِ الثَّانِيَةِ فَكَأَنَّمَا قَرَّبَ بَقَرَةً وَمَنْ رَاحَ فِي السَّاعَةِ الثَّالِثَةِ فَكَأَنَّمَا قَرَّبَ كَبْشًا ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏أَقْرَنَ ‏ ‏وَمَنْ رَاحَ فِي السَّاعَةِ الرَّابِعَةِ فَكَأَنَّمَا قَرَّبَ دَجَاجَةً وَمَنْ رَاحَ فِي السَّاعَةِ الْخَامِسَةِ فَكَأَنَّمَا قَرَّبَ بَيْضَةً فَإِذَا خَرَجَ الْإِمَامُ أَقْبَلَتْ الْمَلَائِكَةُ يَسْتَمِعُونَ الذِّكْرَ ‏","","",""],[9547,9547,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَيَّارٌ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَبَايَعُوا بِالْحَصَاةِ وَلَا ‏ ‏تَنَاجَشُوا ‏ ‏وَلَا تَبَايَعُوا بِالْمُلَامَسَةِ وَمَنْ اشْتَرَى مِنْكُمْ ‏ ‏مُحَفَّلَةً ‏ ‏فَكَرِهَهَا فَلْيَرُدَّهَا وَلْيَرُدَّ مَعَهَا ‏ ‏صَاعًا ‏ ‏مِنْ طَعَامٍ ‏","","",""],[9548,9548,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ مَعَ كُلِّ وُضُوءٍ ‏","","",""],[9549,9549,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا شَرِبَ الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ ‏","","",""],[9550,9550,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏فِي حَدِيثِ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏وَإِسْحَاقَ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏ثُوِّبَ ‏ ‏بِالصَّلَاةِ فَلَا تَأْتُوهَا وَأَنْتُمْ ‏ ‏تَسْعَوْنَ ‏ ‏وَأْتُوهَا وَعَلَيْكُمْ ‏ ‏السَّكِينَةُ ‏ ‏فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا فَاتَكُمْ فَأَتِمُّوا فَإِنَّ أَحَدَكُمْ فِي صَلَاةٍ إِذَا مَا كَانَ ‏ ‏يَعْمِدُ ‏ ‏الصَّلَاةَ ‏","","",""],[9551,9551,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا نُودِيَ لِلصَّلَاةِ ‏ ‏أَدْبَرَ ‏ ‏الشَّيْطَانُ وَلَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ التَّأْذِينَ فَإِذَا قُضِيَ النِّدَاءُ أَقْبَلَ حَتَّى إِذَا ‏ ‏ثُوِّبَ ‏ ‏بِالصَّلَاةِ ‏ ‏أَدْبَرَ ‏ ‏الشَّيْطَانُ وَلَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ التَّأْذِينَ حَتَّى إِذَا ‏ ‏قُضِيَ ‏ ‏التَّثْوِيبُ ‏ ‏أَقْبَلَ ‏ ‏يَخْطِرُ ‏ ‏بَيْنَ الْمَرْءِ وَنَفْسِهِ يَقُولُ اذْكُرْ كَذَا اذْكُرْ كَذَا لِمَا لَمْ يَكُنْ يَذْكُرُ حَتَّى ‏ ‏يَظَلَّ ‏ ‏الرَّجُلُ إِنْ يَدْرِي كَمْ صَلَّى ‏","","",""],[9552,9552,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا السَّائِبِ ‏ ‏مَوْلَى ‏ ‏هِشَامِ بْنِ زُهْرَةَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى صَلَاةً لَمْ يَقْرَأْ فِيهَا ‏ ‏بِأُمِّ الْقُرْآنِ ‏ ‏فَهِيَ ‏ ‏خِدَاجٌ ‏ ‏هِيَ ‏ ‏خِدَاجٌ ‏ ‏هِيَ ‏ ‏خِدَاجٌ ‏ ‏غَيْرُ تَمَامٍ فَقُلْتُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏إِنِّي أَحْيَانًا أَكُونُ وَرَاءَ الْإِمَامِ قَالَ ‏ ‏فَغَمَزَ ‏ ‏ذِرَاعِي وَقَالَ اقْرَأْ بِهَا يَا فَارِسِيُّ فِي نَفْسِكَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏قَسَمْتُ الصَّلَاةَ بَيْنِي وَبَيْنَ عَبْدِي نِصْفَيْنِ فَنِصْفُهَا لِي وَنِصْفُهَا لِعَبْدِي وَلِعَبْدِي مَا سَأَلَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْرَءُوا يَقُولُ الْعَبْدُ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏} ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ حَمِدَنِي عَبْدِي يَقُولُ الْعَبْدُ ‏ { ‏الرَّحْمَنِ الرَّحِيمِ ‏} ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ أَثْنَى عَلَيَّ عَبْدِي يَقُولُ الْعَبْدُ ‏ { ‏مَالِكِ يَوْمِ الدِّينِ ‏} ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ مَجَّدَنِي عَبْدِي يَقُولُ الْعَبْدُ ‏ { ‏إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ‏} ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ هَذِهِ الْآيَةُ بَيْنِي وَبَيْنَ عَبْدِي وَلِعَبْدِي مَا سَأَلَ يَقُولُ الْعَبْدُ ‏ { ‏اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ‏} ‏فَهَؤُلَاءِ لِعَبْدِي وَلِعَبْدِي مَا سَأَلَ ‏","","",""],[9553,9553,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏مِنْ ‏ ‏النَّخْعِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏","","",""],[9554,9554,"","","‏ ‏وَكَانَ ‏ ‏يَكْرَهُ ‏ ‏الشِّكَالَ ‏ ‏مِنْ الْخَيْلِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏يَعْنِي إِحْدَى رِجْلَيْهِ سَوَادٌ أَوْ بَيَاضٌ ‏","","",""],[9555,9555,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ قَالَ ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏سَعِيدَ بْنَ أَبِي سَعِيدٍ الْمَقْبُرِيَّ ‏ ‏بَعْدَمَا كَبِرَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا أَسْفَلُ مِنْ الْكَعْبَيْنِ مِنْ ‏ ‏الْإِزَارِ ‏ ‏فِي النَّارِ ‏","","",""],[9556,9556,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عُثْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا يَحْيَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُغْفَرُ لِلْمُؤَذِّنِ ‏ ‏مَدَّ ‏ ‏صَوْتِهِ وَيَشْهَدُ لَهُ كُلُّ رَطْبٍ وَيَابِسٍ وَشَاهِدُ الصَّلَاةِ يُكْتَبُ لَهُ خَمْسٌ وَعِشْرُونَ وَيُكَفَّرُ عَنْهُ مَا بَيْنَهُمَا ‏","","",""],[9557,9557,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي مَالِكٍ الْأَشْجَعِيِّ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏إِغْرَارَ فِي صَلَاةٍ وَلَا تَسْلِيمٍ ‏","","",""],[9558,9558,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏أَبِي رَهْمٍ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏مِنْ الْمَسْجِدِ فَرَأَى امْرَأَةً تَنْضَخُ طِيبًا لِذَيْلِهَا إِعْصَارٌ قَالَ يَا أَمَةَ الْجَبَّارِ مِنْ الْمَسْجِدِ جِئْتِ قَالَتْ نَعَمْ قَالَ وَلَهُ تَطَيَّبْتِ قَالَتْ نَعَمْ قَالَ فَارْجِعِي فَإِنِّي سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏يَقُولُ ‏ ‏لَا يَقْبَلُ اللَّهُ لِامْرَأَةٍ صَلَاةً تَطَيَّبَتْ لِلْمَسْجِدِ ‏ ‏أَوْ لِهَذَا الْمَسْجِدِ ‏ ‏حَتَّى تَغْتَسِلَ غُسْلَهَا مِنْ الْجَنَابَةِ ‏","","",""],[9559,9559,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ مِينَاءَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَجَدْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏وَاقْرَأْ بِاسْمِ رَبِّكَ ‏","","",""],[9560,9560,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ سَأَلْتُ ‏ ‏أَبَا عَمْرٍو الشَّيْبَانِيَّ ‏ ‏عَنْ قَوْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏إِغْرَارَ فِي الصَّلَاةِ ‏ ‏فَقَالَ ‏ ‏إِنَّمَا هُوَ لَا غِرَارَ فِي الصَّلَاةِ وَمَعْنَى غِرَارٍ يَقُولُ لَا يَخْرُجُ مِنْهَا وَهُوَ يَظُنُّ أَنَّهُ قَدْ بَقِيَ عَلَيْهِ مِنْهَا شَيْءٌ حَتَّى يَكُونَ عَلَى الْيَقِينِ وَالْكَمَالِ ‏","","",""],[9561,9561,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ كَتَبَ إِلَيَّ ‏ ‏مَنْصُورٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا عُثْمَانَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّادِقَ الْمَصْدُوقَ ‏ ‏صَاحِبَ هَذِهِ الْحُجْرَةِ يَقُولُ ‏ ‏لَا تُنْزَعُ الرَّحْمَةُ إِلَّا مِنْ شَقِيٍّ ‏","","",""],[9562,9562,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَجُّ ‏ ‏الْمَبْرُورُ ‏ ‏لَيْسَ لَهُ جَزَاءٌ إِلَّا الْجَنَّةُ وَالْعُمْرَتَانِ ‏ ‏تُكَفِّرَانِ ‏ ‏مَا بَيْنَهُمَا مِنْ الذُّنُوبِ ‏","","",""],[9563,9563,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْإِمَامُ ضَامِنٌ وَالْمُؤَذِّنُ مُؤْتَمَنٌ اللَّهُمَّ أَرْشِدْ الْأَئِمَّةَ وَاغْفِرْ لِلْمُؤَذِّنِينَ ‏","","",""],[9564,9564,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ يَوْمُ صَوْمِ أَحَدِكُمْ فَلَا ‏ ‏يَرْفُثْ ‏ ‏وَلَا يَجْهَلْ فَإِنْ جُهِلَ عَلَيْهِ فَلْيَقُلْ إِنِّي امْرُؤٌ صَائِمٌ ‏","","",""],[9565,9565,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الرَّبِيعُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَشْكُرُ اللَّهَ مَنْ لَا يَشْكُرُ النَّاسَ ‏","","",""],[9566,9566,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏مَوْلَى ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏وَنَحْنُ فِي ‏ ‏مَسْجِدِ الرَّسُولِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَاحِبُ هَذِهِ الْحُجْرَةِ ‏ ‏لَا تُنْزَعُ الرَّحْمَةُ إِلَّا مِنْ شَقِيٍّ ‏","","",""],[9567,9567,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ ‏ ‏الْمِسْكِ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏يَوْمَ الْقِيَامَةِ ‏","","",""],[9568,9568,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلِيمٌ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَهْزٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الصَّوْمُ ‏ ‏جُنَّةٌ ‏ ‏وَإِذَا كَانَ أَحَدُكُمْ يَوْمًا صَائِمًا فَلَا ‏ ‏يَرْفُثْ ‏ ‏وَلَا يَجْهَلْ فَإِنْ أَحَدٌ شَتَمَهُ ‏ ‏أَوْ فَإِنْ امْرُؤٌ شَتَمَهُ ‏ ‏فَلْيَقُلْ إِنِّي صَائِمٌ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فَإِنْ امْرُؤٌ شَتَمَهُ أَوْ قَاتَلَهُ فَلْيَقُلْ إِنِّي صَائِمٌ ‏ ‏وَكَذَا ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَوْ قَاتَلَهُ ‏","","",""],[9569,9569,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعُمْرَةُ ‏ ‏تُكَفِّرُ ‏ ‏مَا بَيْنَهَا وَبَيْنَ الْعُمْرَةِ وَالْحَجُّ ‏ ‏الْمَبْرُورُ ‏ ‏لَيْسَ لَهُ جَزَاءٌ إِلَّا الْجَنَّةُ ‏","","",""],[9570,9570,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلِيمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّوْمُ ‏ ‏جُنَّةٌ ‏","","",""],[9571,9571,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي الضَّحَّاكِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ عَامٍ لَا يَقْطَعُهَا شَجَرَةَ الْخُلْدِ ‏","","",""],[9572,9572,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَخْطُبُ أَحَدُكُمْ عَلَى خِطْبَةِ أَخِيهِ ‏","","",""],[9573,9573,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُجْمَعُ بَيْنَ الْمَرْأَةِ وَعَمَّتِهَا وَلَا بَيْنَ الْمَرْأَةِ وَخَالَتِهَا ‏","","",""],[9574,9574,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الصَّلَاةِ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ وَعَنْ الصَّلَاةِ بَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ ‏","","",""],[9575,9575,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏وَعَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏وَعَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَدْرَكَ رَكْعَةً مِنْ الْعَصْرِ قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ فَقَدْ أَدْرَكَ الْعَصْرَ وَمَنْ أَدْرَكَ رَكْعَةً مِنْ الصُّبْحِ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَقَدْ أَدْرَكَ ‏","","",""],[9576,9576,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏مَوْلَى ‏ ‏الْأَسْوَدِ بْنِ سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏وَمُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ الْحَرُّ ‏ ‏فَأَبْرِدُوا ‏ ‏بِالصَّلَاةِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ وَذَكَرَ أَنَّ النَّارَ اشْتَكَتْ إِلَى رَبِّهَا فَأَذِنَ لَهَا فِي كُلِّ عَامٍ بِنَفَسَيْنِ نَفَسٍ فِي الشِّتَاءِ وَنَفَسٍ فِي الصَّيْفِ ‏","","",""],[9577,9577,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اشْتَدَّ الْحَرُّ ‏ ‏فَأَبْرِدُوا ‏ ‏عَنْ الصَّلَاةِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏","","",""],[9578,9578,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ يَدْخُلُ الْجَنَّةَ يَنْعَمُ وَلَا يَبْأَسُ لَا ‏ ‏تَبْلَى ‏ ‏ثِيَابُهُ وَلَا ‏ ‏يَفْنَى شَبَابُهُ إِنَّ فِي الْجَنَّةِ مَا لَا عَيْنٌ رَأَتْ وَلَا أُذُنٌ سَمِعَتْ وَلَا خَطَرَ عَلَى قَلْبِ بَشَرٍ ‏","","",""],[9579,9579,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَجُلًا زَارَ أَخًا لَهُ فِي قَرْيَةٍ أُخْرَى فَأَرْصَدَ اللَّهُ عَلَى مَدْرَجَتِهِ مَلَكًا فَقَالَ لَهُ أَيْنَ تَذْهَبُ قَالَ أَزُورُ أَخًا لِي فِي اللَّهِ فِي قَرْيَةِ كَذَا وَكَذَا قَالَ هَلْ لَهُ عَلَيْكَ مِنْ نِعْمَةٍ تَرُبُّهَا قَالَ لَا وَلَكِنَّنِي أَحْبَبْتُهُ فِي اللَّهِ عَزَّ وَجَلَّ قَالَ فَإِنِّي رَسُولُ اللَّهِ إِلَيْكَ ‏ ‏أَنَّ اللَّهَ قَدْ أَحَبَّكَ كَمَا أَحْبَبْتَهُ فِيهِ ‏","","",""],[9580,9580,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَعَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ ‏ ‏يَسْتَامَ ‏ ‏الرَّجُلُ عَلَى ‏ ‏سَوْمِ ‏ ‏أَخِيهِ أَوْ يَخْطُبَ عَلَى خِطْبَتِهِ ‏","","",""],[9581,9581,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اشْتَرَى شَاةً ‏ ‏مُصَرَّاةً ‏ ‏فَلْيَحْلِبْهَا فَإِنْ لَمْ يَرْضَهَا فَلْيَرُدَّهَا وَلْيَرُدَّ مَعَهَا ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ ‏","","",""],[9582,9582,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سَأَلَهُ جَارُهُ أَنْ ‏ ‏يَغْرِزَ ‏ ‏خَشَبَةً فِي جِدَارِهِ فَلَا يَمْنَعْهُ ‏","","",""],[9583,9583,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُثَنَّى بْنُ سَعِيدٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هُمَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَاتَلَ أَحَدُكُمْ فَلْيَجْتَنِبْ الْوَجْهَ ‏ ‏قَالَ ‏ ‏ابْنُ مَهْدِيٍّ ‏ ‏فَإِنَّ اللَّهَ عَزَّ وَجَلَّ خَلَقَ ‏ ‏آدَمَ ‏ ‏عَلَى صُورَتِهِ ‏","","",""],[9584,9584,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏زُهَيْرٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏تَنْذِرُوا ‏ ‏فَإِنَّ ‏ ‏النَّذْرَ ‏ ‏لَا يَرُدُّ شَيْئًا مِنْ الْقَدَرِ وَإِنَّمَا يُسْتَخْرَجُ بِهِ مِنْ الْبَخِيلِ ‏","","",""],[9585,9585,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏زُهَيْرٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ عَبْدِي وَأَمَتِي كُلُّكُمْ عَبِيدُ اللَّهِ وَكُلُّ نِسَائِكُمْ إِمَاءُ اللَّهِ وَلَكِنْ لِيَقُلْ غُلَامِي وَجَارِيَتِي وَفَتَايَ وَفَتَاتِي ‏","","",""],[9586,9586,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا قَعَدَ قَوْمٌ مَقْعَدًا لَا يَذْكُرُونَ اللَّهَ عَزَّ وَجَلَّ وَيُصَلُّونَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا كَانَ عَلَيْهِمْ حَسْرَةً يَوْمَ الْقِيَامَةِ وَإِنْ دَخَلُوا الْجَنَّةَ ‏ ‏لِلثَّوَابِ ‏","","",""],[9587,9587,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي فَإِنَّ الشَّيْطَانَ لَا يَتَمَثَّلُ بِمِثْلِي ‏","","",""],[9588,9588,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يُؤْذِ جَارَهُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَسْكُتْ ‏","","",""],[9589,9589,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ اللَّهُمَّ اغْفِرْ لِي إِنْ شِئْتَ اللَّهُمَّ ارْحَمْنِي إِنْ شِئْتَ وَلَكِنْ ‏ ‏لِيَعْزِمْ ‏ ‏الْمَسْأَلَةَ فَإِنَّهُ لَا مُكْرِهَ لَهُ ‏","","",""],[9590,9590,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏اسْتَجْمَرَ ‏ ‏فَلْيُوتِرْ ‏","","",""],[9591,9591,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَسْكُتْ ‏","","",""],[9592,9592,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ مَنْعِ ‏ ‏فَضْلِ ‏ ‏الْمَاءِ لِيُمْنَعَ بِهِ ‏ ‏الْكَلَأُ ‏","","",""],[9593,9593,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّا ‏ ‏مَعْشَرَ ‏ ‏الْأَنْبِيَاءِ ‏ ‏لَا نُورَثُ مَا تَرَكْتُ بَعْدَ ‏ ‏مَئُونَةِ ‏ ‏عَامِلِي وَنَفَقَةِ نِسَائِي ‏ ‏صَدَقَةٌ ‏","","",""],[9594,9594,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَطْلُ ‏ ‏الْغَنِيِّ ظُلْمٌ وَمَنْ ‏ ‏أُحِيلَ ‏ ‏عَلَى مَلِيءٍ ‏ ‏فَلْيَحْتَلْ ‏","","",""],[9595,9595,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَوْلَى النَّاسِ ‏ ‏بِعِيسَى ‏ ‏الْأَنْبِيَاءُ إِخْوَةٌ أَوْلَادُ ‏ ‏عَلَّاتٍ ‏ ‏وَلَيْسَ بَيْنِي وَبَيْنَ ‏ ‏عِيسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏نَبِيٌّ ‏","","",""],[9596,9596,"","","‏ ‏حَدَّثَنَا ‏ ‏عُمَرَ بْنُ سَعْدٍ وَهُوَ أَبُو دَاوُدَ الْحَفَرِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ يَعْنِي الْأَعْرَجَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَوْلَى النَّاسِ ‏ ‏بِعِيسَى ‏ ‏الْأَنْبِيَاءُ أَبْنَاءُ ‏ ‏عَلَّاتٍ ‏ ‏وَلَيْسَ بَيْنِي وَبَيْنَ ‏ ‏عِيسَى ‏ ‏نَبِيٌّ ‏","","",""],[9597,9597,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَضْحَكُ اللَّهُ إِلَى رَجُلَيْنِ يَقْتُلُ أَحَدُهُمَا الْآخَرَ كِلَاهُمَا يَدْخُلُ الْجَنَّةَ يُقَاتِلُ هَذَا فِي سَبِيلِ اللَّهِ فَيُسْتَشْهَدُ قَالَ ثُمَّ يَتُوبُ اللَّهُ عَلَى قَاتِلِهِ فَيُسْلِمُ فَيُقَاتِلُ فِي سَبِيلِ اللَّهِ حَتَّى يُسْتَشْهَدَ ‏","","",""],[9598,9598,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُسَمُّوا الْعِنَبَ الْكَرْمَ فَإِنَّمَا الْكَرْمُ الرَّجُلُ الْمُسْلِمُ ‏","","",""],[9599,9599,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْمَطْلُ ‏ ‏ظُلْمُ الْغَنِيِّ وَمَنْ ‏ ‏أُتْبِعَ ‏ ‏عَلَى مَلِيءٍ ‏ ‏فَلْيَتْبَعْ ‏","","",""],[9600,9600,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ اللَّهُمَّ اغْفِرْ لِي إِنْ شِئْتَ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا مُسْتَكْرِهَ لَهُ وَلَكِنْ ‏ ‏لِيَعْزِمْ ‏ ‏فِي الْمَسْأَلَةِ ‏","","",""]];
